     "expr": "datum.tr.reason == 'ber_saturated' || (datum.ber || 0) >= 16.7"
    },
    {
     "type": "formula",
     "as": "berc",
     "expr": "datum.sat ? 1.2e-7 : max(datum.ber || 0, 1.2e-7)"
    },
    {
     "type": "formula",
     "as": "berv",
     "expr": "datum.sat ? null : datum.ber"
    },
