     "as": [
      "pv",
      "n3"
     ]
    },
    {
     "type": "formula",
     "as": "chg",
     "expr": "datum.view != datum.pv ? 1 : 0"
    },
    {
     "type": "window",
     "groupby": [
      "side"
     ],
     "sort": {
      "field": "t"
     },
     "ops": [
      "sum"
